        let zipPath = null;

        let finalPdfBuffers = [];

        if (!isMultiplePdf) {
            console.log("Generando PDF único");
            const documents = await fetchDocuments(request_id);
            zipPath = await generatePDFsAndZip(documents, signedAt, request_id);
        } else {
            console.log("Generando PDFs individuales");
            for (let i = 0; i < pdfBuffers.length; i++) {
                const pdfBuffer = pdfBuffers[i].buffer;
                const document_hash = documentHashes[i]?.document_hash || "SIN_HASH";

                const pdfDoc = await PDFDocument.load(pdfBuffer);
                const numPages = pdfDoc.getPages().length;
                const lastPage = pdfDoc.getPages()[numPages - 1];

                const footerText = `ID: ${document_hash}; Completado el: ${moment.utc(signedAt).tz('America/Bogota').format('YYYY-MM-DD HH:mm:ss')}`;

                const qrImgValidation = await qr.toDataURL(process.env.URL_CERTICATE_VALIDATION + "?id=" + request_id);
                const qrImage = await pdfDoc.embedPng(Buffer.from(qrImgValidation.split(",")[1], "base64"));

                pdfDoc.getPages().forEach((page, pageIndex) => {
                    const pageQrArea = {
                        x: page.getWidth() - 80,
                        y: 20,
                        width: 60,
                        height: 60
                    };

                    if (pageIndex === numPages - 1) {
                        page.drawImage(qrImage, {
                            x: pageQrArea.x - 40,
                            y: pageQrArea.y + 40,
                            width: pageQrArea.width,
                            height: pageQrArea.height,
                        });

                        page.drawText('Validación certificado', {
                            x: pageQrArea.x - 60,
                            y: pageQrArea.y + 30,
                            size: 9,
                            color: rgb(0, 0, 0),
                        });
                    }

                    page.drawText(footerText, {
                        x: 20,
                        y: 10,
                        size: 9,
                        color: rgb(0, 0, 0),
                    });
                });

                const finalPdfBuffer = Buffer.from(await pdfDoc.save());
                finalPdfBuffers.push({ name: pdfBuffers[i].name, buffer: finalPdfBuffer });
            }
        }

        await Promise.all(
            emails.map(async (email) => {
                await sendEmailWithAttachment(
                    transporter,
                    email,
                    isMultiplePdf ? finalPdfBuffers : zipPath,
                    groupName,
                    companyName,
                    isMultiplePdf
                );
            })
        );

    } catch (e) {
        console.error("Error en el envío de correos grupales:", e);
        throw e;
    }
}

