const moment = require('moment-timezone');

function generateHeaderTemplate(headerData) {
    if (!headerData || Object.keys(headerData).length === 0) {
        return "<span></span>";
    }

    return `
        <div style="
            width: 100%;
            display: flex;
            justify-content: ${headerData.justifyContent}; 
            align-items: center;
            height: 70px;
            padding: 0 15mm;
            box-sizing: border-box;
        ">
            <div style="display: flex; align-items: center;">
                <div style="flex-shrink: 0;">
                    <img
                        src="${headerData.imageBase64}"
                        style="
                            display: block;
                            width: ${headerData.imageWidth}px;
                            height: ${headerData.imageHeight || 'auto'}px;
                            max-height: 60px;
                        "
                    >
                </div>
                <div style="
                    color: #000;
                    font-size: 10px;
                    opacity: 0.5;
                    margin-left: 15px;
                ">
                    ${headerData.text}
                </div>
            </div>
        </div>
    `;
}

function generateFooterTemplate(footerData, documentInfo) {
    let customPart = '';
    if (footerData && footerData.imageBase64) {
        customPart = `
            <div style="display: flex; align-items: center; justify-content: flex-start;">
                <img
                    src="${footerData.imageBase64}"
                    style="display: block; width: ${footerData.imageWidth}px; height: ${footerData.imageHeight || 'auto'}px; max-height: 40px;"
                >
                <div style="font-size: 10px; opacity: 0.5; margin-left: 10px;">
                    ${footerData.text || ''}
                </div>
            </div>
        `;
    }

    let documentPart = '';
    const details = [];
    if (documentInfo && documentInfo.hash) {
        details.push(`ID: ${documentInfo.hash}`);
    }
    if (documentInfo && documentInfo.completionDate) {
        const date = moment.utc(documentInfo.completionDate).tz('America/Bogota').format('YYYY-MM-DD HH:mm');
        details.push(`Completado: ${date}`);
    }
    if (details.length > 0) {
        documentPart = `<div style="font-size: 10px; color: #555; text-align: right;">${details.join('; ')}</div>`;
    }

    if (!customPart && !documentPart) return "<span></span>";

    return `
        <div style="
            width: 100%;
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 5mm 15mm;
            box-sizing: border-box;
            margin-top: 15px;      
            padding-top: 5px;    
            padding-left: 15mm;    
            padding-right: 15mm;   
            padding-bottom: 0;
            font-family: Arial, sans-serif;
            border-top: 1px solid #e0e0e0; 
        ">
            <div>${customPart}</div>
            <div>${documentPart}</div>
        </div>
    `;
}

module.exports = {
    generateHeaderTemplate,
    generateFooterTemplate,
};

