async function fetchDocumentContent(privateKey, s3_key) {
    const s3Params = { Bucket: process.env.S3_BUCKET, Key: s3_key };

    const data = await s3Client.send(new GetObjectCommand(s3Params))
    const token = await data.Body.transformToString('utf-8');
    const decoded = jwt.verify(token, privateKey, { algorithms: ["RS512"] });
    return decoded.pdf;
}

async function generatePDF(htmlContent, document, request_id, signedAt) {
    const browser = await puppeteer.launch({ headless: true });
    const page = await browser.newPage();
    await page.setContent(htmlContent);

    const options = {
        margin: {
            top: '22mm',  
            right: '19mm',    
            bottom: '22mm',
            left: '19mm',
        },       
    };

    const width = document.document_packages_details.template.custom_width;
    const height = document.document_packages_details.template.custom_height;

    const header = document.document_packages_details.template.header_content;
    const footer = document.document_packages_details.template.footer_content;

    if (width && height) {
        options.width = width + 'cm';
        options.height = height + 'cm';
    } else {
        options.format = document.document_packages_details.template.paper_size || 'Letter';
    }

    if (header && Object.keys(header).length > 0) {
        options.displayHeaderFooter = true;
        options.printBackground = true;

        const header_content = JSON.parse(header);
        if (header_content.text || header_content.imageBase64) {
            options.displayHeaderFooter = true;
            options.printBackground = true;
            options.headerTemplate = `
                <div style="display: flex; justify-content: ${header_content.justifyContent || 'left'}; padding: 0;">
                    ${header_content.imageBase64 ? `<img src="${header_content.imageBase64}" style="max-width: 100%; height: auto;">` : ''}
                    ${header_content.text ? `<div style="color: #000000; font-size: 10px; opacity: 0.5;">${header_content.text}</div>` : ''}
                </div>`;
