                <div style="text-align: center; font-size: 9px; color: #000;">
                    ID: ${document.document_hash}; Completado el: ${moment(signedAt).tz('America/Bogota').format('YYYY-MM-DD HH:mm:ss')}
                </div>`;
        }
    }

    if (!header || header === "{}" || Object.keys(JSON.parse(header)).length === 0) {
        options.headerTemplate = "<span></span>"; 
    }


    if (!footer || footer === "{}" || Object.keys(JSON.parse(footer)).length === 0) {
        options.footerTemplate =`
            <div style="
                position: relative;
                margin-bottom: -20px;
                width: 100%; 
            ">
                <div style="
                    bottom: 0;
                    font-size: 9px;
                    color: #000;
                    text-align: center;
