Ya tengo el panorama completo de los 13 puntos. Aquí va el código paso a paso:

---

## Paso 1: Instalar `p-limit`

```bash
cd C:/Users/Hope/Documents/firma_prod/firmadigital/firma_digital_backend
npm install p-limit
```

---

## Paso 2: Crear `services/puppeteer/browserPool.js`

Este es el módulo central. Crear el archivo con este contenido:

```js
const puppeteer = require("puppeteer");

const MAX_CONCURRENT_PAGES = 3; // Para t3.large (2 vCPUs), máximo 3 pages simultáneas

let browser = null;
let activePages = 0;
let waitQueue = [];

const LAUNCH_ARGS = [
    '--no-sandbox',
    '--disable-setuid-sandbox',
    '--disable-dev-shm-usage',
    '--disable-gpu',
    '--disable-extensions',
    '--disable-background-networking',
    '--disable-default-apps',
    '--disable-translate',
    '--no-first-run',
    '--single-process',
    '--no-zygote',
];

async function getBrowser() {
    if (!browser || !browser.connected) {
        browser = await puppeteer.launch({
            headless: 'new',
            args: LAUNCH_ARGS,
        });

        browser.on('disconnected', () => {
            console.warn('[BrowserPool] Browser disconnected. Will relaunch on next request.');
            browser = null;
            // Rechazar todos los que están esperando
            while (waitQueue.length > 0) {
                const { reject } = waitQueue.shift();
                reject(new Error('Browser disconnected while waiting for page'));
            }
        });

        console.log('[BrowserPool] Browser launched.');
    }
    return browser;
}

/**
 * Obtiene una page del browser compartido.
 * Si ya hay MAX_CONCURRENT_PAGES activas, espera en cola.
 */
async function getPage() {
    if (activePages >= MAX_CONCURRENT_PAGES) {
        await new Promise((resolve, reject) => {
            waitQueue.push({ resolve, reject });
        });
    }

    activePages++;
    const b = await getBrowser();
    const page = await b.newPage();
    return page;
}

/**
 * Libera una page. Siempre llamar en un bloque finally.
 */
async function releasePage(page) {
    try {
        if (page && !page.isClosed()) {
            await page.close();
        }
    } catch (err) {
        console.error('[BrowserPool] Error closing page:', err.message);
    } finally {
        activePages = Math.max(0, activePages - 1);

        if (waitQueue.length > 0) {
            const { resolve } = waitQueue.shift();
            resolve();
        }
    }
}

/**
 * Cierra el browser completamente (para shutdown graceful del servidor).
 */
async function closeBrowser() {
    if (browser) {
        try {
            await browser.close();
        } catch (err) {
            console.error('[BrowserPool] Error closing browser:', err.message);
        }
        browser = null;
        activePages = 0;
        waitQueue = [];
        console.log('[BrowserPool] Browser closed.');
    }
}

function getStats() {
    return {
        browserConnected: browser ? browser.connected : false,
        activePages,
        waitingInQueue: waitQueue.length,
    };
}

module.exports = {
    getPage,
    releasePage,
    closeBrowser,
    getStats,
};
```

---

## Paso 3: Registrar el shutdown graceful

En el archivo principal del servidor (probablemente `index.js` del backend), agregar al final:

```js
const { closeBrowser } = require('./services/puppeteer/browserPool');

process.on('SIGTERM', async () => {
    console.log('SIGTERM received. Closing browser pool...');
    await closeBrowser();
    process.exit(0);
});

process.on('SIGINT', async () => {
    console.log('SIGINT received. Closing browser pool...');
    await closeBrowser();
    process.exit(0);
});
```

