## Paso 5: Control de concurrencia en `generatePDFsAndZip` (services/index.js)

Este es el loop masivo en la línea 1726. Cambiar de secuencial a paralelo controlado:

```js
// ANTES (líneas 1726-1749):
async function generatePDFsAndZip(documents, signedAt, request_id) {
    const zipPath = 'pdfs.zip';
    const archive = archiver('zip', { zlib: { level: 9 } });
    const output = fs.createWriteStream(zipPath);
    archive.pipe(output);
    const private_key = fs.readFileSync("./my_key.key", "utf-8");
    for (const doc of documents) {
        try {
            const htmlContent = await fetchDocumentContent(private_key, doc.s3_key);
            const pdfBuffer = await generatePDF(htmlContent, doc, signedAt, request_id);

            if (pdfBuffer && pdfBuffer.length > 0) {
                 archive.append(pdfBuffer, { name: `${doc.name}.pdf` });
            }
        } catch (err) {
            console.error("Error generando PDF para zippear:", err);
        }
    }
    await new Promise((resolve, reject) => {
        output.on('close', resolve);
        archive.on('error', reject);
        archive.finalize();
    });
    return zipPath;
}

// DESPUÉS:
const pLimit = require('p-limit');

async function generatePDFsAndZip(documents, signedAt, request_id) {
    const zipPath = 'pdfs.zip';
    const archive = archiver('zip', { zlib: { level: 9 } });
    const output = fs.createWriteStream(zipPath);
    archive.pipe(output);
    const private_key = fs.readFileSync("./my_key.key", "utf-8");

    const limit = pLimit(2); // Máximo 2 PDFs generándose en paralelo

    const tasks = documents.map(doc =>
        limit(async () => {
            try {
                const htmlContent = await fetchDocumentContent(private_key, doc.s3_key);
                const pdfBuffer = await generatePDF(htmlContent, doc, signedAt, request_id);

                if (pdfBuffer && pdfBuffer.length > 0) {
                    archive.append(pdfBuffer, { name: `${doc.name}.pdf` });
                }
            } catch (err) {
                console.error("Error generando PDF para zippear:", err);
            }
        })
    );

    await Promise.all(tasks);

    await new Promise((resolve, reject) => {
        output.on('close', resolve);
        archive.on('error', reject);
        archive.finalize();
    });
    return zipPath;
}
```

