const fs = require("fs");
const https = require("https");
const http = require("http");
const cors = require("cors");
const bodyParser = require("body-parser");
const express = require("express");
const session = require("express-session");
const morgan = require("morgan");
const helmet = require("helmet");
let history = require('connect-history-api-fallback');
const api = require("./api");
const rateLimit = require('express-rate-limit');
let cookieParser = require("cookie-parser");
const { auth } = require("express-openid-connect");
let FileStore = require("session-file-store")(session);
const swaggerUi = require('swagger-ui-express');
const YAML = require('yamljs');
const queues = require("./bull-queues");
const { closeBrowser } = require('./services/puppeteer/browserPool');
require('dotenv').config();

const isProduction = process.env.NODE_ENV === 'production';
const HTTP_PORT = process.env.HTTP_PORT || 8182;
const HTTPS_PORT = process.env.HTTPS_PORT || 8443; 
const DOMAIN = process.env.DOMAIN;
const SSL_BASE_PATH = process.env.SSL_CERT_BASE_PATH;

BigInt.prototype.toJSON = function () {
    return parseInt(this);
};

const app = express();

app.disable('x-powered-by');

app.use(
    session({
        secret: process.env.SESSION_SECRET,
        resave: false,
        saveUninitialized: false,
        store: new FileStore(), 
        cookie: {
            maxAge: 24 * 60 * 60 * 1000, 
            secure: isProduction, 
            httpOnly: true, 
            sameSite: 'lax' 
        }
    })
);

app.use(cors({
    credentials: true,
    origin: (origin, callback) => {
        if (!origin) {
            return callback(null, true);
        }

        if (origin.startsWith('http://localhost') || 
            origin === 'https://quality-sign.co' || 
            origin.endsWith('.quality-sign.co')) 
        {
            callback(null, true);
        } else {
            callback(new Error('Acceso no permitido por la política de CORS.'));
        }
    }
}));

app.use(morgan("dev"));


app.use(bodyParser.urlencoded({ limit: "50mb", extended: true }));
app.use(bodyParser.json({ limit: "50mb" }));

app.use(helmet()); 
app.use(helmet.frameguard({ action: 'deny' }));

app.use( helmet.contentSecurityPolicy({
    directives: {
        defaultSrc: ["'self'"],
        scriptSrc: ["'self'"],
        styleSrc: ["'self'", "https://fonts.googleapis.com"],
        fontSrc: ["'self'", "https://fonts.gstatic.com"],
        imgSrc: ["'self'", "data:"],
        connectSrc: ["'self'"],
        objectSrc: ["'none'"],
        upgradeInsecureRequests: [],
    },
}));

app.use(
  helmet.referrerPolicy({
    policy: 'no-referrer',
  })
);

app.use(helmet.crossOriginResourcePolicy({ policy: 'same-origin' }));

app.use(cookieParser());

const swaggerDocument = YAML.load('./swagger.yaml');
app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));

const limiter = rateLimit({
    windowMs: 15 * 60 * 1000, 
    max: 1000,
    standardHeaders: true, 
    legacyHeaders: false, 
    message: 'Demasiadas peticiones desde esta IP, por favor intenta de nuevo después de 15 minutos.'
});

app.use('/api', limiter);

const config = {
    authRequired: false,
    auth0Logout: true,
    secret: process.env.AUTH0_SECRET, 
    baseURL: process.env.BASE_URL, 
    clientID: process.env.AUTH0_CLIENT_ID, 
    issuerBaseURL: process.env.AUTH0_ISSUER_BASE_URL, 
};

app.use(auth(config));

app.use("/api", api);
app.use(history());

/* 
(async () => {
    try {
        console.log("Iniciando cola de validación...");

        Object.entries(queues).forEach(([queueName, queue]) => {
            queue.on("completed", (job) => {
                console.log(`Trabajo completado en ${queueName}: ${job.id}`);
            });

            queue.on("failed", (job, err) => {
                console.error(`Error en ${queueName} trabajo ${job.id}:`, err);
            });
        });


        console.log("Cola de validación configurada.");
    } catch (error) {
        console.error("Error al iniciar la cola de validación:", error);
    }
})(); */

process.on('SIGTERM', async () => {
    await closeBrowser();
    process.exit(0);
});

process.on('SIGINT', async () => {
    await closeBrowser();
    process.exit(0);
});

if (isProduction) {

    if (!DOMAIN || !SSL_BASE_PATH) {
        throw new Error('Las variables de entorno DOMAIN y SSL_CERT_BASE_PATH son requeridas en producción.');
    }

    const sslOptions = {
        key: null,
        cert: null,
        ca: null
    };

    try {
        const keyPath = `${SSL_BASE_PATH}${DOMAIN}/privkey.pem`;
        const certPath = `${SSL_BASE_PATH}${DOMAIN}/cert.pem`;
        const caPath = `${SSL_BASE_PATH}${DOMAIN}/chain.pem`;

        sslOptions.key = fs.readFileSync(keyPath);
        sslOptions.cert = fs.readFileSync(certPath);
        sslOptions.ca = fs.readFileSync(caPath);

    } catch (error) {
        console.error('Error al leer los archivos de certificado SSL:', error);
        process.exit(1); 
    }

    const httpsServer = https.createServer(sslOptions, app);

    httpsServer.listen(HTTPS_PORT, () => {
        console.log(`Servidor HTTPS corriendo en el puerto ${HTTPS_PORT} para el dominio ${DOMAIN}`);
    });

} else {
    const httpServer = http.createServer(app);

    httpServer.listen(HTTP_PORT, () => {
        console.log(`Servidor HTTP de desarrollo corriendo en http://localhost:${HTTP_PORT}`);
    });
}

