async function generateAndSubmitFinalPDF(documentPackageSigner,  documentPackageUpdated, htmlDocs) {
    if (!htmlDocs || htmlDocs.length === 0) {
        console.error("No se encontraron documentos HTML para generar el PDF.");
        return;
    }

    console.log("Generando PDF final para el paquete firmado ID:", documentPackageUpdated );

    const doc = htmlDocs[0]; 
    const { htmlContent, header, footer, paperSize, customWidth, customHeight } = doc;

    const document_hash = await db.document_packages_signers_details_values.findFirst({
        where: {
            document_package_signer_id: parseInt(documentPackageSigner.id),
            id: doc.id,
        },
        select: { document_hash: true },
    });

    const browser = await puppeteer.launch({ headless: 'new' });
    const page = await browser.newPage();
    await page.setContent(htmlContent, { waitUntil: 'domcontentloaded' });

    const options = {
        margin: { top: '22mm', right: '19mm', bottom: '22mm', left: '19mm' },
        printBackground: true,
        displayHeaderFooter: true, 
        format: (!paperSize || paperSize.toLowerCase() === 'other') ? 'A4' : paperSize,
        ...(customWidth && customHeight && { width: `${customWidth}cm`, height: `${customHeight}cm` }),
    };

    options.headerTemplate = generateHeaderTemplate(header ? JSON.parse(header) : null);

    console.log("Generando PDF con las siguientes opciones:", documentPackageUpdated);
    const documentInfo = {
        hash: document_hash.document_hash,
        completionDate: documentPackageUpdated, 
    };

    options.footerTemplate = generateFooterTemplate(footer ? JSON.parse(footer) : null, documentInfo);

    const pdfBuffer = await page.pdf(options);
    await browser.close();

    const pdfDoc = await PDFDocument.load(pdfBuffer);
    const lastPage = pdfDoc.getPages()[pdfDoc.getPageCount() - 1];

    const qrImgValidation = await qr.toDataURL(`${process.env.URL_CERTICATE_VALIDATION}?id=${documentPackageSigner.document_package_signer_id}`);
    const qrImage = await pdfDoc.embedPng(Buffer.from(qrImgValidation.split(",")[1], "base64"));

    lastPage.drawImage(qrImage, { x: 480, y: 50, width: 60, height: 60 });
    lastPage.drawText('Validación certificado', { x: 465, y: 35, size: 10, color: rgb(0, 0, 0) });

    const finalPdfBuffer = Buffer.from(await pdfDoc.save());
    const pdfBase64 = finalPdfBuffer.toString('base64');

    await notifyExternalAPI(documentPackageSigner, "accepted", pdfBase64);
}

