async function htmlToPdf(html, header, footer, document_hash, updated_at) {
    try {

        const browser = await puppeteer.launch({headless: true});
        const page = await browser.newPage();
        await page.setContent(html);

        const margin = {
            top: '22mm',  
            right: '19mm',    
            bottom: '22mm',
            left: '19mm',
        };

        let header_content = header ? JSON.parse(header) : null;
        let footer_content = footer ? JSON.parse(footer) : null;

        let pages_pdf;


        const options = {
            format: 'Letter',
            margin: margin,
            displayHeaderFooter: true,
            printBackground: true
        };

        options.headerTemplate = generateHeaderTemplate(header_content ? header_content : null);

        const documentInfo = {
            hash: document_hash,
            completionDate: updated_at, 
        };

        options.footerTemplate = generateFooterTemplate(footer_content ? footer_content : null, documentInfo);

        pages_pdf = await page.pdf(options);


        await page.evaluate(() => window.close()); 
        await browser.close();

        return pages_pdf;

    } catch (error) {

    }
}

