## PASO 1 — Crear archivo nuevo `services/puppeteer/browserPool.js`

La carpeta `services/puppeteer/` ya existe y está vacía. Crear dentro el archivo `browserPool.js` con este contenido exacto:

```js
const puppeteer = require("puppeteer");

const MAX_CONCURRENT_PAGES = 3;

let browser = null;
let activePages = 0;
let waitQueue = [];

const LAUNCH_ARGS = [
    '--no-sandbox',
    '--disable-setuid-sandbox',
    '--disable-dev-shm-usage',
    '--disable-gpu',
    '--disable-extensions',
    '--disable-background-networking',
    '--disable-default-apps',
    '--disable-translate',
    '--no-first-run',
    '--single-process',
    '--no-zygote',
];

async function getBrowser() {
    if (!browser || !browser.connected) {
        browser = await puppeteer.launch({
            headless: 'new',
            args: LAUNCH_ARGS,
        });

        browser.on('disconnected', () => {
            console.warn('[BrowserPool] Browser disconnected. Will relaunch on next request.');
            browser = null;
            while (waitQueue.length > 0) {
                const { reject } = waitQueue.shift();
                reject(new Error('Browser disconnected while waiting for page'));
            }
        });

        console.log('[BrowserPool] Browser launched.');
    }
    return browser;
}

async function getPage() {
    if (activePages >= MAX_CONCURRENT_PAGES) {
        await new Promise((resolve, reject) => {
            waitQueue.push({ resolve, reject });
        });
    }

    activePages++;
    const b = await getBrowser();
    const page = await b.newPage();
    return page;
}

async function releasePage(page) {
    try {
        if (page && !page.isClosed()) {
            await page.close();
        }
    } catch (err) {
        console.error('[BrowserPool] Error closing page:', err.message);
    } finally {
        activePages = Math.max(0, activePages - 1);

        if (waitQueue.length > 0) {
            const { resolve } = waitQueue.shift();
            resolve();
        }
    }
}

async function closeBrowser() {
    if (browser) {
        try {
            await browser.close();
        } catch (err) {
            console.error('[BrowserPool] Error closing browser:', err.message);
        }
        browser = null;
        activePages = 0;
        waitQueue = [];
        console.log('[BrowserPool] Browser closed.');
    }
}

function getStats() {
    return {
        browserConnected: browser ? browser.connected : false,
        activePages,
        waitingInQueue: waitQueue.length,
    };
}

module.exports = {
    getPage,
    releasePage,
    closeBrowser,
    getStats,
};
```

